package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for NumberUtils.isNumber to maximize branch and line coverage.
 */
public class NumberUtils_isNumber_TriageGen2Test {

    @Test
    public void testIsNumber_NullAndEmpty() {
        assertFalse("Null should return false", NumberUtils.isNumber(null));
        assertFalse("Empty string should return false", NumberUtils.isNumber(""));
    }

    @Test
    public void testIsNumber_Integers() {
        assertTrue("Simple integer", NumberUtils.isNumber("123"));
        assertTrue("Negative integer", NumberUtils.isNumber("-123"));
        assertTrue("Zero", NumberUtils.isNumber("0"));
        assertTrue("Integer with sign", NumberUtils.isNumber("+123"));
        assertFalse("Just a sign", NumberUtils.isNumber("-"));
        assertFalse("Just a plus", NumberUtils.isNumber("+"));
    }

    @Test
    public void testIsNumber_Decimals() {
        assertTrue("Decimal", NumberUtils.isNumber("123.45"));
        assertTrue("Negative decimal", NumberUtils.isNumber("-123.45"));
        assertTrue("Trailing decimal point", NumberUtils.isNumber("123."));
        assertTrue("Leading decimal point", NumberUtils.isNumber(".123"));
        assertFalse("Multiple decimal points", NumberUtils.isNumber("1.2.3"));
        assertFalse("Decimal in exponent", NumberUtils.isNumber("1e2.3"));
        assertFalse("Just a dot", NumberUtils.isNumber("."));
    }

    @Test
    public void testIsNumber_Hexadecimal() {
        assertTrue("Hex lowercase", NumberUtils.isNumber("0x1a2b"));
        assertTrue("Hex uppercase", NumberUtils.isNumber("0xABCDEF"));
        assertTrue("Hex with negative", NumberUtils.isNumber("-0x123"));
        assertTrue("Hex with zero", NumberUtils.isNumber("0x0"));
        assertFalse("Hex incomplete", NumberUtils.isNumber("0x"));
        assertFalse("Hex invalid char", NumberUtils.isNumber("0x12G3"));
        assertFalse("Hex with decimal", NumberUtils.isNumber("0x1.2"));
    }

    @Test
    public void testIsNumber_ScientificNotation() {
        assertTrue("Exponent lowercase", NumberUtils.isNumber("1e10"));
        assertTrue("Exponent uppercase", NumberUtils.isNumber("1E10"));
        assertTrue("Exponent with negative sign", NumberUtils.isNumber("1e-10"));
        assertTrue("Exponent with positive sign", NumberUtils.isNumber("1e+10"));
        assertTrue("Negative base exponent", NumberUtils.isNumber("-1e10"));
        assertFalse("Exponent without digit before", NumberUtils.isNumber("e10"));
        assertFalse("Exponent without digit after", NumberUtils.isNumber("1e"));
        assertFalse("Exponent with sign but no digit", NumberUtils.isNumber("1e-"));
        assertFalse("Multiple exponents", NumberUtils.isNumber("1e2e3"));
    }

    @Test
    public void testIsNumber_TypeQualifiers() {
        // d, D, f, F (decimals/floats)
        assertTrue("Float suffix f", NumberUtils.isNumber("123f"));
        assertTrue("Float suffix F", NumberUtils.isNumber("123F"));
        assertTrue("Double suffix d", NumberUtils.isNumber("123d"));
        assertTrue("Double suffix D", NumberUtils.isNumber("123D"));
        assertTrue("Float suffix with decimal", NumberUtils.isNumber("123.45f"));

        // l, L (longs) - restricted by logic: !hasExp && !hasDecPoint
        assertTrue("Long suffix l", NumberUtils.isNumber("123l"));
        assertTrue("Long suffix L", NumberUtils.isNumber("123L"));
        assertFalse("Long suffix with exponent", NumberUtils.isNumber("1e2l"));
        assertFalse("Long suffix with decimal", NumberUtils.isNumber("123.4l"));

        // Invalid suffixes
        assertFalse("Invalid suffix", NumberUtils.isNumber("123z"));
    }

    @Test
    public void testIsNumber_EdgeCases() {
        // Testing the logic around the loop end and the last character check
        assertFalse("Trailing E", NumberUtils.isNumber("123E"));
        assertTrue("Digit at end after loop logic", NumberUtils.isNumber("123"));

        // Testing allowSigns and foundDigit interaction
        // The loop condition: while (i < sz || (i < sz + 1 && allowSigns && !foundDigit))
        // This handles cases like "1e+" where it might try to check the sign
        assertFalse("Sign at end", NumberUtils.isNumber("1e+"));
        assertFalse("Sign at end negative", NumberUtils.isNumber("1e-"));

        // Test characters that are not allowed
        assertFalse("Space", NumberUtils.isNumber("1 2"));
        assertFalse("Alpha", NumberUtils.isNumber("abc"));
    }
}
